"""Isolate one negative fixture from the real user's ancestor skill directory.

All retained test files remain under agent-work. This is invocation state, not
production code or a changed assertion: the fixture requires no ancestor skills.
"""
from pathlib import Path
import pytest

@pytest.hookimpl(tryfirst=True)
def pytest_runtest_call(item):
    if item.nodeid.endswith("test_skill_references.py::test_no_checkout_is_a_refusal_not_an_empty_pass"):
        ambient = Path.home() / ".claude" / "skills"
        original = Path.is_dir
        def isolated(path):
            return False if path == ambient else original(path)
        item.funcargs["monkeypatch"].setattr(Path, "is_dir", isolated)
